CREATE TABLE IF NOT EXISTS shopping_chat_threads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_key text NOT NULL,customer_id uuid REFERENCES customers(id) ON DELETE SET NULL,product_id uuid REFERENCES products(id) ON DELETE SET NULL,product_name text NOT NULL,request_key uuid NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')),version integer NOT NULL DEFAULT 1,awaiting_admin boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_key,request_key));
CREATE INDEX IF NOT EXISTS shopping_chat_owner ON shopping_chat_threads(owner_key,updated_at);
CREATE TABLE IF NOT EXISTS shopping_chat_messages(id bigserial PRIMARY KEY,thread_id uuid NOT NULL REFERENCES shopping_chat_threads(id) ON DELETE CASCADE,sender text NOT NULL CHECK(sender IN ('customer','admin')),body text NOT NULL CHECK(length(body) BETWEEN 1 AND 3000),request_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(thread_id,request_key));
CREATE INDEX IF NOT EXISTS shopping_chat_message_thread ON shopping_chat_messages(thread_id,id);
